"""Offline exact recovery for reviewed shards and regenerated bytecode only."""
from __future__ import annotations

import argparse
import ctypes
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import py_compile
import re
import shutil
import struct
import subprocess
import sys
import tempfile

sys.path.insert(0,str(Path(__file__).resolve().parent))
import bundles
import state
from deferred_state import E, ROOT

LOCK = E/'RESTORE-LOCK.json.gz'
ARCHIVES = ROOT/'docs/research-archives/photo-prompt'


def regular(root, relative):
    bundles.safe_name(relative)
    p=Path(root)
    if p.is_symlink():raise ValueError('symlink source root')
    for part in Path(relative).parts:
        p=p/part
        if p.is_symlink():raise ValueError('symlink recovery source')
    if not p.is_file():raise ValueError('missing recovery source')
    return p


def publish_exclusive(source,destination):
    library=ctypes.CDLL(None,use_errno=True)
    rename=getattr(library,'renamex_np',None)
    if rename is None:raise ValueError('exclusive atomic directory publication is unavailable')
    rename.argtypes=[ctypes.c_char_p,ctypes.c_char_p,ctypes.c_uint]
    rename.restype=ctypes.c_int
    if rename(os.fsencode(source),os.fsencode(destination),4)!=0:  # Darwin RENAME_EXCL
        number=ctypes.get_errno()
        raise OSError(number,os.strerror(number),str(destination))


def restore_rows(rows,destination,backend='sealed',repository=ROOT):
    destination=Path(destination)
    if destination.exists() or destination.is_symlink():raise ValueError('destination already exists')
    if backend not in ('git','sealed'):raise ValueError('unknown recovery backend')
    names=[r['path'] for r in rows]
    if not rows or len(names)!=len(set(names)):raise ValueError('empty or duplicate recovery member list')
    for r in rows:
        bundles.safe_name(r['path'])
        if not re.fullmatch('[0-9a-f]{64}',r['sha256']) or r['bytes']<0 or not 0<=r['mode']<=0o777:
            raise ValueError('invalid recovery member')
        if backend=='git' and not re.fullmatch('[0-9a-f]{40,64}',r['git_blob']):
            raise ValueError('invalid Git blob identity')
    # A new sibling tree is promoted atomically after every member validates.
    parent=destination.parent.resolve();parent.mkdir(parents=True,exist_ok=True)
    destination=parent/destination.name
    if destination.exists() or destination.is_symlink():raise ValueError('resolved destination exists')
    with tempfile.TemporaryDirectory(prefix='.deferred-restore-',dir=parent) as temp:
        staged=Path(temp)/'root';staged.mkdir();child=None
        try:
            if backend=='git':
                child=subprocess.Popen(['/usr/bin/sandbox-exec','-p','(version 1)(allow default)(deny network*)',
                    'git','--no-lazy-fetch','-C',str(repository),'cat-file','--batch'],
                    stdin=subprocess.PIPE,stdout=subprocess.PIPE,
                    env=dict(os.environ,GIT_NO_LAZY_FETCH='1'))
            for row in rows:
                if child:
                    child.stdin.write((row['git_blob']+'\n').encode());child.stdin.flush()
                    header=child.stdout.readline().decode().strip().split()
                    if len(header)!=3 or header[0]!=row['git_blob'] or header[1]!='blob':
                        raise ValueError('Git object unavailable or wrong type; no fetch')
                    size=int(header[2])
                    if size!=row['bytes']:raise ValueError('Git object size differs')
                    raw=child.stdout.read(size)
                    if child.stdout.read(1)!=b'\n':raise ValueError('truncated Git object')
                else:
                    raw=regular(row['sealed_generation'],row['sealed_relative']).read_bytes()
                if len(raw)!=row['bytes'] or hashlib.sha256(raw).hexdigest()!=row['sha256']:
                    raise ValueError('recovery member hash differs: '+row['path'])
                p=staged/row['path'];p.parent.mkdir(parents=True,exist_ok=True)
                with p.open('xb') as stream:stream.write(raw)
                p.chmod(row['mode'])
        finally:
            if child:
                child.stdin.close();child.stdout.close()
                if child.wait(timeout=10)!=0:raise ValueError('Git object reader failed')
        # Never overwrite a destination created by another writer during extraction.
        if destination.exists() or destination.is_symlink():raise ValueError('restore collision')
        publish_exclusive(staged,destination)
    return destination


def load_lock():
    if (E/'STAGE02.json').exists() and state.sha(LOCK)!=state.read(E/'STAGE02.json')['restore_lock_sha256']:
        raise ValueError('sealed recovery lock changed')
    return state.read(LOCK)


def restore_shards(destination,backend,group=None):
    rows=[r for r in load_lock()['shards'] if group is None or r['group']==group]
    return restore_rows(rows,destination,backend)


def compile_child(specification,destination):
    rows=state.read(specification);destination=Path(destination)
    for row in rows:
        raw=Path(row['source']).read_bytes()
        if hashlib.sha256(raw).hexdigest()!=row['source_sha256']:raise ValueError('recovery source changed')
        header=bytes.fromhex(row['header_hex'])
        if header[:4]!=importlib.util.MAGIC_NUMBER:raise ValueError('recovery interpreter differs')
        flags=struct.unpack('<I',header[4:8])[0]
        modes={0:py_compile.PycInvalidationMode.TIMESTAMP,1:py_compile.PycInvalidationMode.UNCHECKED_HASH,
               3:py_compile.PycInvalidationMode.CHECKED_HASH}
        with tempfile.TemporaryDirectory(prefix='photo-compile-source-') as temp:
            source=Path(temp)/'source.py';source.write_bytes(raw)
            if flags==0:
                mtime=struct.unpack('<I',header[8:12])[0];os.utime(source,(mtime,mtime))
            target=destination/row['path'];target.parent.mkdir(parents=True,exist_ok=True)
            py_compile.compile(str(source),cfile=str(target),dfile=row['compiled_owner'],doraise=True,
                optimize=row['optimization'],invalidation_mode=modes[flags])
        if state.sha(target)!=row['cache_sha256']:raise ValueError('bytecode recovery differs')
        target.chmod(row['mode'])


def prove():
    if (E/'STAGE02.json').exists():raise ValueError('recovery proof already sealed')
    targets=state.read(E/'TARGETS.json.gz');baseline=state.read(E/'BASELINE.json.gz')
    commit=baseline['repositories'][str(ROOT)]['head'];shards=targets['shards']
    raw=state.git(ROOT,'ls-tree','-rz',commit,'--',*[r['path'] for r in shards])
    blobs={}
    for record in raw.split(b'\0'):
        if not record:continue
        header,path=record.decode().split('\t',1);mode,kind,oid=header.split()
        if kind!='blob' or mode not in ('100644','100755'):raise ValueError('nonregular Git recovery member')
        blobs[path]=oid
    groups={r['id']:r for r in shards};rows=[]
    for target in targets['targets']:
        if target['group']=='bytecode':continue
        rel=target['path'];group=groups[target['group']];before=target['before']
        if target['preflight']!='READY' or state.sha(ROOT/rel)!=target['expected_sha256']:
            raise ValueError('target changed before recovery qualification')
        rows.append({'path':rel,'group':target['group'],'sha256':target['expected_sha256'],
            'bytes':before['bytes'],'mode':before['mode'],'git_commit':commit,'git_blob':blobs[rel],
            'sealed_generation':group['duplicate']['generation'],
            'sealed_relative':'assets/photo_candidate_search_shards/'+target['group']+'/'+Path(rel).name})
    state.write(LOCK,{'schema':'photo-deferred-recovery/v1','shards':rows,'git_commit':commit})
    with tempfile.TemporaryDirectory(prefix='photo-deferred-recovery-proof-') as temp:
        temp=Path(temp);proof=[]
        for backend in ('git','sealed'):
            restored=restore_shards(temp/backend,backend)
            count=sum(1 for p in restored.rglob('*') if p.is_file())
            if count!=5770:raise ValueError('recovery coverage differs')
            proof.append({'backend':backend,'files':count,'logical_bytes':sum(r['bytes'] for r in rows),'status':'PASS'})
            shutil.rmtree(restored)
            print('shard recovery PASS:',backend,count,flush=True)
        source=bundles.restore(ARCHIVES/'source-review-and-lane-experiments.zip',
            state.read(ARCHIVES/'EXPERIMENT-LOCK.json'),temp/'experiment')
        bytecodes=[r for r in targets['targets'] if r['group']=='bytecode'];specifications={}
        for target in bytecodes:
            row=target['analysis'];p=ROOT/target['path'];cache=p.read_bytes()
            if hashlib.sha256(cache).hexdigest()!=row['cache_sha256']:raise ValueError('cache changed')
            original=row['source'];src=ROOT/original if row['source_origin']=='working_source' else source/original
            tag=re.search(r'cpython-(\d+)',p.name).group(1)
            opt=re.search(r'\.opt-([012])\.pyc$',p.name)
            specifications.setdefault(tag,[]).append({'path':target['path'],'source':str(src),
                'source_origin':row['source_origin'],'source_sha256':row['source_sha256'],
                'header_hex':cache[:16].hex(),'compiled_owner':str(ROOT/original),
                'optimization':int(opt.group(1)) if opt else 0,'cache_sha256':row['cache_sha256'],
                'mode':target['before']['mode']})
        interpreter_proofs=[];compiled=temp/'compiled'
        for tag,spec in specifications.items():
            executable=Path('/opt/homebrew/bin/python3.12') if tag=='312' else Path(sys.executable)
            path=temp/('compile-'+tag+'.json');state.write(path,spec)
            env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1')
            subprocess.run([str(executable),'-I',str(Path(__file__).resolve()),'compile-child',str(path),str(compiled)],
                check=True,env=env,timeout=60)
            interpreter_proofs.append({'tag':tag,'executable':str(executable.resolve()),
                'executable_sha256':state.sha(executable.resolve()),'files':len(spec),
                'sources':[{k:v for k,v in r.items() if k!='source'} for r in spec]})
        seal=bundles.pack(E/'BYTECODE-RECOVERY.zip',{r['path']:compiled/r['path'] for r in bytecodes})
        bundles.restore(E/'BYTECODE-RECOVERY.zip',seal,temp/'bytecode-restored')
        state.write(E/'BYTECODE-RECOVERY-LOCK.json',seal)
        state.write(E/'BYTECODE-REGENERATION.json',interpreter_proofs)
        state.write(E/'STAGE02.json',{'status':'PASS','restore_lock_sha256':state.sha(LOCK),
            'shard_backends':proof,'bytecodes_reproduced':len(bytecodes),'bytecode_bytes':sum(r['before']['bytes'] for r in bytecodes),
            'bytecode_recovery_archive_sha256':seal['archive_sha256'],'new_large_archive':False,
            'Gemini_calls':0,'CURRENT_writes':0})
    print('stage 2 recovery PASS: 5770 shards via two backends; 45 exact bytecodes',flush=True)


if __name__=='__main__':
    # -I keeps the pinned compiler isolated; only this explicit maintenance path is added.
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('command',choices=['prove','restore','compile-child'])
    parser.add_argument('path',nargs='?');parser.add_argument('destination',nargs='?')
    parser.add_argument('--backend',choices=['git','sealed'],default='git');parser.add_argument('--group')
    args=parser.parse_args()
    if args.command=='prove':prove()
    elif args.command=='restore':restore_shards(args.path,args.backend,args.group)
    else:compile_child(args.path,args.destination)
